-- Fleur d'Ombre
  description, perfumer, year, accent, featured, availability, display_order, is_published)
values (
  'f0514274-ac68-484e-8fa8-facee2bb2906', 'fleur-dombre', 'Fleur d''Ombre', 'Eau de Parfum', 'Floral', 'Tuberose in half-light, cooled by iris and clean musk.',
  $txt$A white flower composition built for restraint. Tuberose and jasmine are given room to breathe, then shaded with orris butter until the effect is powdery rather than heady.

The drydown is quiet skin musk — the flowers recede but never quite leave.$txt$, 'Marc Vaugelas', 2019, '#c98f9b', true, 'available', 2, true
);

-- Bois Cendré
  description, perfumer, year, accent, featured, availability, display_order, is_published)
values (
  '5582542e-cbb9-4f7e-8dd0-7cf800307430', 'bois-cendre', 'Bois Cendré', 'Eau de Parfum', 'Woody', 'Dry cedar and a curl of woodsmoke over warm paper.',
  $txt$Bois Cendré is the smell of a room the morning after a fire has burned down. Cedar and guaiac wood carry a soft ash note, kept from going grey by a little tonka.

It sits on the skin as texture more than sweetness — matte, sober, and long.$txt$, 'Élodie Rançon', 2022, '#9a7b5a', true, 'available', 3, true
